await step('Mở Thiết lập chung IoT (/iot/config/rating)', async () => {
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Không tải được màn hình Thiết lập chung IoT');
});

await step('Mở Cấu hình nhân viên phụ trách IoT (/iot/config/employee)', async () => {
  await page.goto('https://tasks.zuizui.io/iot/config/employee', { waitUntil: 'domcontentloaded' });
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const txt = await page.locator('body').innerText();
  assert(txt.length > 50, 'Không tải được màn hình Cấu hình phụ trách IoT');
  ctx.log('Đã kiểm tra các màn hình Thiết lập IoT.');
});
